{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I protest my property taxes in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "File a written notice of protest with your appraisal district by May 15, or 30 days after the district mails your notice of appraised value, whichever is later. Comptroller Form 50-132 works. The appraisal review board must give at least 15 days notice of the hearing, which you may attend in person, by phone, by video or by affidavit."
      }
    },
    {
      "@type": "Question",
      "name": "What is the Texas property tax protest deadline?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "May 15, or 30 days after the appraisal district mails the notice of appraised value, whichever is later. The clock runs from the mailing date, not the date you receive it. If the deadline falls on a weekend or legal holiday it moves to the next business day."
      }
    },
    {
      "@type": "Question",
      "name": "When does the appraisal district have to send my notice of appraised value?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "By May 1, or by April 1 for a residence homestead, or as soon as practical thereafter under Tax Code 25.19. Because homesteads get the earlier notice, homeowners generally have more time to prepare a protest than owners of other property types."
      }
    },
    {
      "@type": "Question",
      "name": "Do I have to appear in person at an ARB hearing in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. An owner may appear in person, by telephone or videoconference, or by submitting a written affidavit. The appraisal review board must give at least 15 days notice of the hearing date, time and place."
      }
    },
    {
      "@type": "Question",
      "name": "What does a Texas notice of protest have to say?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It must be in writing and identify the property, the owner, and a subject showing the owner is dissatisfied with a determination of the appraisal district. Comptroller Form 50-132 is the standard form, and most districts accept online filing, but no specific format is required."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I terminate a real estate contract in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You terminate a Texas contract by exercising a right the contract gives you and delivering written notice — most commonly during the option period using TREC form 38-8. Terminating the contract and getting the earnest money back are two separate events: escrowed funds cannot be released without mutual agreement or a court order."
      }
    },
    {
      "@type": "Question",
      "name": "What form do I use to terminate a contract during the option period in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "TREC's Notice of Buyer's Termination of Contract, form 38-8, effective 04/01/2025. Paragraph 5B of form 20-19 requires notice of termination to the seller by 5:00 p.m. local time where the Property is located, by the date specified. The option fee will not be refunded and any earnest money will be refunded to the buyer."
      }
    },
    {
      "@type": "Question",
      "name": "Can I terminate a Texas contract after the option period ends?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Only if another right applies. The Third Party Financing Addendum, form 40-11, creates a financing exit with its own deadline, and the appraisal addendum, form 49-1, covers a low appraisal. Inside form 20-19, paragraph 7B(2) covers a missing seller's disclosure notice, paragraph 6B covers a title commitment that never arrives, paragraph 6D covers uncured title objections, and paragraph 14 covers casualty loss. Each requires written notice before its deadline."
      }
    },
    {
      "@type": "Question",
      "name": "What if the seller never gave me the disclosure notice in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Paragraph 7B(2) of TREC form 20-19 says that if the buyer does not receive the Seller's Disclosure Notice, the buyer may terminate at any time prior to the closing with the earnest money refunded. If the seller then delivers it, the buyer may terminate for any reason within 7 days after receiving it or prior to closing, whichever first occurs."
      }
    },
    {
      "@type": "Question",
      "name": "Does terminating the contract automatically return my earnest money in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Termination and escrow release are separate. Earnest money in escrow cannot be released to either party without mutual agreement or a court order, so a seller who declines to sign the release leaves the funds sitting even after the contract has ended."
      }
    },
    {
      "@type": "Question",
      "name": "Can a seller terminate a contract in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Only where the contract gives the seller a right, typically after a buyer default and any required cure period. TREC's Notice of Seller's Termination of Contract, form 50-0, papers that right but does not create one. A seller wanting out because a better offer arrived should talk with a Texas real estate attorney first."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How does the option fee work in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The option fee is a negotiated amount the buyer delivers to the escrow agent — the title company, not the seller — within three days after the effective date. It pays for the unrestricted right to terminate. If the sale closes, the fee is credited to the sales price. If the buyer terminates, the seller keeps it."
      }
    },
    {
      "@type": "Question",
      "name": "Who does the option fee get paid to in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The escrow agent, which is the title company handling the transaction. It is not paid to the seller directly and not to the listing agent. The escrow agent may then release the fee to the seller before closing, without the buyer's consent, once good funds are received."
      }
    },
    {
      "@type": "Question",
      "name": "What is the deadline to deliver the option fee in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Paragraph 5A of TREC form 20-19 requires delivery within 3 days after the Effective Date, to the Escrow Agent named in the contract rather than to the seller. Paragraph 5A(2) extends the deadline if the last day is a Saturday, Sunday or Legal Holiday as defined in Texas Government Code Sections 662.003(a) and 662.003(b)(4) and (6). Paragraph 5E states time is of the essence."
      }
    },
    {
      "@type": "Question",
      "name": "Can the option fee and earnest money be paid together in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Paragraph 5A says they may be paid separately or combined in a single payment. Paragraph 5A(3) applies amounts received first to the option fee, then to the earnest money, then to any additional earnest money. An underfunded combined payment therefore leaves the earnest money short, which is a buyer default."
      }
    },
    {
      "@type": "Question",
      "name": "What happens if the option fee amount is left blank in a Texas contract?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Paragraph 5D of TREC form 20-19 states that if no dollar amount is stated as the option fee, or if the buyer fails to deliver it within the time required, the buyer shall not have the unrestricted right to terminate under paragraph 5. A blank option fee kills the termination right just as completely as a late payment, even though an option period is written into the contract."
      }
    },
    {
      "@type": "Question",
      "name": "How much is the option fee in Texas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "There is no statutory or TREC-set amount. Paragraph 5A of form 20-19 is a fill-in-the-blank dollar figure the buyer and seller negotiate, and it generally tracks the length of the option period and how competitive the offer needs to be."
      }
    }
  ]
}

